SELECT
FROM `order` o LEFT JOIN product p ON o.product_id = p.id LEFT JOIN base_user bu ON o.buyer_id = bu.id LEFT JOIN base_user su ON o.seller_id = su.id LEFT JOIN address a ON o.address_id = a.id
o.buyer_id = #{buyerId}
AND o.order_status = #{query.orderStatus}
AND o.order_no LIKE concat('%', #{query.keyword}, '%')
ORDER BY o.create_time DESC
LIMIT #{query.current}, #{query.size}

